<span class="line"><span style="color:#C678DD;">        string</span><span style="color:#E5C07B;"> queue</span><span style="color:#ABB2BF;">, </span><span style="color:#E5C07B;">TimeSpan</span><span style="color:#E5C07B;"> timeout</span><span style="color:#ABB2BF;">)</span></span>
